  try { hasExcerpt = ((await env.AUDIT.prepare("PRAGMA table_info(cf_changelog_items)").all()).results || []).some(function(r) { return r.name === "excerpt"; }); } catch (eP) { console.error(JSON.stringify({ evt: "fleet-control:cfcSchema:columns", error: String(eP && eP.message) })); }
