  var openRows = await charterRows(env, "SELECT id, title FROM agent_issues WHERE status = 'open' AND (title LIKE 'METRIC-REGRESSION-1:%' OR title LIKE 'METRIC-FIX-RELAPSED-1:%')");
  var openByTitle = {};
