function tpKey(l) {
  return "TP-" + l.tp + "." + l.n + "-" + String(l.key || "").toUpperCase().replace(/[^A-Z0-9]+/g, "-").replace(/^-|-$/g, "") + "-1";
}
function tpIssueTitle(l) {
  return (tpKey(l) + ": " + String(l.title || "")).slice(0, 180);
}
