  var evs = jrn2xx(r.status) ? jrnParseSse(r.text) : [];
  if (!jrnCheck(j, "ask streams", jrn2xx(r.status) && evs.length, "http " + r.status + ", " + evs.length + " events" + (r.timedOut ? " (stream still open at the " + Math.round(r.timedOut / 1000) + " s timeout)" : ""))) return j;
  var meta = (evs.filter(function(e) { return e[0] === "meta" && e[1]; })[0] || [null, {}])[1] || {};
  var sources = meta.sources || [];
  var answer = evs.filter(function(e) { return e[0] === "token" && e[1]; }).map(function(e) { return e[1].t || ""; }).join("");
  var done = evs.some(function(e) { return e[0] === "done"; });
