  (answer.match(/\[(\d+(?:\s*,\s*\d+)*)\]/g) || []).forEach(function(g) { g.replace(/\d+/g, function(n) { n = Number(n); if (cites.indexOf(n) < 0) cites.push(n); return n; }); });
  cites.sort(function(a, b) { return a - b; });
