  jrnCheck(j, "telemetry 5xx filter applied", non5 === 0, non5 + " of " + t5.events.length + " returned events below 500");
  var by = {};
  t5.events.forEach(function(e) { if (!e.script || e.status < 500) return; var b = by[e.script] || (by[e.script] = { n: 0, routes: {} }); b.n++; var k = (e.path || "?") + " " + e.status; b.routes[k] = (b.routes[k] || 0) + 1; });
  try {
    var grp = (await db.prepare("SELECT json_extract(payload, '$.service') AS svc, json_extract(payload, '$.title') AS title, json_extract(payload, '$.lastObserved') AS lo FROM fleet_issue_dispatch WHERE category = 'worker-observability' AND json_extract(payload, '$.title') LIKE 'HttpServerError%' AND json_extract(payload, '$.lastObserved') > ?1").bind(now5 - JRN_TRAFFIC_WINDOW_MS).all()).results || [];
    var blind = grp.filter(function(g) { return g.svc && !by[g.svc]; }).map(function(g) { return g.svc + " (" + g.title + ")"; });
    jrnCheck(j, "telemetry sees every 5xx group Cloudflare Issues reports in 6 h", !blind.length, blind.join("; "));
    // CF-ISSUES-LOOP-1 (0.27.0): Cloudflare's own grouping of recurring failures. Every error group (exceptions and error logs; the
    // vulnerability-scanner probes are other people's requests) observed in the window is a real-traffic failure the fleet must act on.
    var errg = (await db.prepare("SELECT json_extract(payload, '$.service') AS svc, json_extract(payload, '$.title') AS title FROM fleet_issue_dispatch WHERE category = 'worker-observability' AND json_extract(payload, '$.status') = 'active' AND json_extract(payload, '$.lastObserved') > ?1 AND json_extract(payload, '$.title') NOT LIKE 'Potential vulnerability scan%' AND json_extract(payload, '$.title') NOT LIKE 'HttpServerError%' ORDER BY json_extract(payload, '$.lastObserved') DESC LIMIT 30").bind(now5 - JRN_TRAFFIC_WINDOW_MS).all()).results || [];
    jrnCheck(j, "no Cloudflare Observability error group recurred in 6 h", !errg.length, errg.map(function(g) { return g.svc + ": " + String(g.title).slice(0, 90); }).join("; "));
  } catch (e) { /* the Issues ledger is optional evidence */ }
