    rows = (await db.prepare("SELECT c.class, c.issue_id, c.escalate_to, c.deferred_since, c.attempts FROM remediation_contracts c WHERE " + RT_STILL_DEFERRED_SQL + " AND c.deferred_since <= datetime('now', ?1) AND NOT EXISTS (SELECT 1 FROM agent_issues x WHERE x.id = c.issue_id AND x.title LIKE ?2 || '%') AND NOT EXISTS (SELECT 1 FROM agent_issues o WHERE o.status = 'open' AND lower(trim(o.title)) = lower(trim(?2 || c.class))) ORDER BY c.deferred_since LIMIT ?3").bind("-" + RT_DEFERRAL_ESCALATE_MIN + " minutes", RT_DEFERRAL_ISSUE_PREFIX, room).all()).results || [];
