  + "FROM agent_issues p JOIN agent_issues a ON a.id = CAST(substr(p.title, length('PROBE-NEEDED-1: issue-') + 1) AS INTEGER) "
  + "WHERE p.status = 'open' AND p.title LIKE 'PROBE-NEEDED-1: issue-%' AND length(substr(p.title, length('PROBE-NEEDED-1: issue-') + 1)) > 0 AND substr(p.title, length('PROBE-NEEDED-1: issue-') + 1) NOT GLOB '*[^0-9]*' AND a.status = 'open' "
  + "AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN ('active', 'holding') AND instr(c.verify_probe, 'needs-machine' || '-probe') = 0 AND instr(c.verify_probe, 'SELECT status FROM agent_issues WHERE' || ' id =') = 0 AND instr(c.verify_probe, 'agent_issues WHERE id = ' || a.id || ')') = 0) "
  + "AND NOT EXISTS (SELECT 1 FROM cloud_ops_events e WHERE e.kind IN ('remediation.probe-author-reject', 'remediation.probe-authored') AND e.text LIKE 'issue=' || a.id || ' %' AND e.ts > strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-' || ?1 || ' hours')) "
