    var rc = await db.prepare("SELECT issue_id, status, last_verdict FROM remediation_contracts WHERE issue_id IN (" + list + ") ORDER BY CASE status WHEN 'active' THEN 0 WHEN 'holding' THEN 1 ELSE 2 END").all();
